def emit(record):
    stream = io.StringIO()
    handler = logging.StreamHandler(stream)
    handler.setFormatter(logging.Formatter("%(message)s"))
    logger = logging.Logger(record.name)
    logger.propagate = False
    logger.addHandler(handler)
    logger.addFilter(OAuthAccessFilter())
    try:
        logger.handle(record)
    finally:
        logger.removeHandler(handler)
        handler.close()
    return stream.getvalue().rstrip("\n")


@pytest.mark.parametrize("case,target,expected", CANONICAL[::4], ids=[row[0] for row in CANONICAL[::4]])
@pytest.mark.parametrize("style", ["uvicorn", "gunicorn", "SafeAtoms", "ws"], ids=["uvicorn", "gunicorn", "SafeAtoms", "ws"])
def test_actual_log_records_preserve_sinks_and_safe_atoms(case, target, expected, style):
    if style == "uvicorn":
        record = logging.LogRecord("uvicorn.access", logging.INFO, __file__, 1,
            '%s - "%s %s HTTP/%s" %d', ("client", "GET", target, "1.1", 200), None)
        assert emit(record) == f'client - "GET {expected} HTTP/1.1" 200'
    elif style == "ws":
        record = logging.LogRecord("uvicorn.error", logging.INFO, __file__, 1,
            '%s - "WebSocket %s" [accepted]', ("client", target), None)
        assert emit(record) == f'client - "WebSocket {expected}" [accepted]'
    else:
        raw_path = target.split("?", 1)[0]
        values = {"U": raw_path, "q": "private_note=SYNTHETIC_PRIVATE_QUERY", "m": "GET", "H": "HTTP/1.1",
            "r": "GET " + target + " HTTP/1.1", "f": target, "{referer}i": target,
            "{authorization}i": "SYNTHETIC_AUTH", "{cookie}i": "SYNTHETIC_COOKIE",
            "{custom}i": 'ordinary"value'}
        atoms = SafeAtoms(values) if style == "SafeAtoms" else values
        before = dict(atoms)
        record = logging.LogRecord("gunicorn.access", logging.INFO, __file__, 1,
            '%(U)s|%(r)s|%(q)s|%(f)s|%({referer}i)s|%({authorization}i)s|%({cookie}i)s', (atoms,), None)
        assert emit(record) == "|".join([expected, "GET " + expected + " HTTP/1.1", "", expected, expected,
                                        "[redacted]", "[redacted]"])
        assert dict(atoms) == before and record.args is not atoms and type(record.args) is type(atoms)
        if style == "SafeAtoms":
            assert record.args["missing"] == "-" and record.args["{ABSENT}i"] == "-"
            assert record.args["{Custom}i"] == 'ordinary\\"value'


@pytest.mark.parametrize("case,target,expected", ALIASES[::10], ids=[row[0] for row in ALIASES[::10]])
def test_aliases_in_absolute_referrers_and_gunicorn_request_line(case, target, expected):
    atoms = SafeAtoms({"U": target, "q": "token=SYNTHETIC_QUERY", "r": "GET " + target + " HTTP/1.1",
        "m": "GET", "H": "HTTP/1.1", "f": "https://example.invalid" + target,
        "{referer}i": "https://example.invalid" + target})
    record = logging.LogRecord("gunicorn.access", logging.INFO, __file__, 1,
        '%(U)s|%(r)s|%(q)s|%(f)s|%({referer}i)s', (atoms,), None)
    assert emit(record) == "|".join([expected, "GET " + expected + " HTTP/1.1", "", expected, expected])


def test_installation_idempotence_and_logger_state_cleanup():
    names = ("uvicorn.access", "gunicorn.access", "uvicorn.error")
    saved = {name: list(logging.getLogger(name).filters) for name in names}
    try:
        for name in names:
            logging.getLogger(name).filters = []
        install_oauth_access_filters()
        install_oauth_access_filters()
        for name in names:
            assert len(logging.getLogger(name).filters) == 1
            assert isinstance(logging.getLogger(name).filters[0], OAuthAccessFilter)
    finally:
        for name in names:
            logging.getLogger(name).filters = saved[name]
    assert all(logging.getLogger(name).filters == saved[name] for name in names)


